def _parse_env_lines(text: str) -> dict[str, str]:
    values: dict[str, str] = {}
    for raw in text.splitlines():
        if not raw or "=" not in raw:
            continue
        key, value = raw.split("=", 1)
        if key:
            values[key] = value
    return values


