def _flag_map(args: list[str]) -> dict[str, str]:
    opts: dict[str, str] = {}
    idx = 0
    while idx < len(args):
        if args[idx].startswith("--") and idx + 1 < len(args) and not args[idx + 1].startswith("--"):
            opts[args[idx]] = args[idx + 1]
            idx += 2
        elif args[idx].startswith("--"):
            opts[args[idx]] = ""
            idx += 1
        else:
            idx += 1
    return opts
